import type { Canvas, Ink, Reel } from '../canvas'
import { noise } from '../canvas'

// Ghost line (Ghost in the Shell). Three variants, 48 frames each, one
// catchphrase each. Every variant opens and closes on a dark frame (every cell
// under 0.10 luminance in both themes), so any variant can follow any other.
//
// camo: a night skyline of dark red towers with lit windows. The Major stands
// on a roof ledge in yellow and lets her coat fall. THERMOPTIC CAMO: the camo
// wipes down her body top to bottom behind a yellow scan line, leaving a
// see-through, hollow aqua outline that shimmers. She tips back off the roof
// and drops down her tower's dark face while the lit city streams up past her
// on both sides; her outline breaks up and is gone, and the lights go out at
// street level.
//
// net-dive: a dark field of hex digits. A diver drops into the center.
// DIVE // SECTION 9: the splash, two yellow wavefronts racing out to the edges
// rewriting every digit they cross. Their aqua echoes run back and meet in the
// middle, then a red sweep crosses from one side. Digits change only at a front.
//
// lattice: the net grows out of one node at the center, an aqua diamond lattice
// over a dark red harlequin, its crossings lighting aqua as it reaches them.
// THE NET IS VAST AND INFINITE: every crossing blazes yellow at once. Then the
// lattice flows outward from the center without end while yellow packets race
// along its links, each lighting the cell it crosses, and it dims to dark.
//
// The seed picks the skyline, windows, where she stands and where the coat
// falls; the digits the splash and echoes write, and the sweep's side; the
// packets' routes and times. The idle field and the sweep's digits are
// seed-free, so the field reads the same across a loop wrap.

const LOOP = 48

// camo
const WIPE = 12 // the camo wipe starts: THERMOPTIC CAMO
const TIP = 20 // she tips off the ledge
const FALL = 22 // the camera follows her down: the city streams up a pixel a frame
const FADE = [36, 44] as const // her outline breaks up and is gone
const DARK = 46 // the street: the lights are out

// net-dive
const SPLASH = 8 // DIVE // SECTION 9
const ECHO = 16 // the echoes start back from the edges
const SWEEP = 26 // the red sweep starts

// lattice
const BLAZE = 12 // THE NET IS VAST AND INFINITE
const FLOW = 18 // the lattice starts to flow outward

const HEX = '0123456789ABCDEF'

// The Major, 6 dots wide and 7 tall: standing (torso and coat filled), then
// spread as she falls. The camo keeps only a pose's edge dots.
const STAND = ['..XX..', '..XX..', '.XXXX.', 'XXXXXX', '.XXXX.', '.X..X.', '.X..X.']
const SPREAD = ['X.XX.X', '.XXXX.', '..XX..', '..XX..', '.X..X.', 'X....X', '......']

const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v))

function camo(c: Canvas, f: number, seed: number) {
  const dim = (s: 'deep' | 'hot') => c.mix(s, 'base', s === 'deep' ? 0.25 : 0.5)
  const dark = f === 0 || f >= DARK
  const s = clamp(f - FALL + 1, 0, DARK - FALL) // camera drop in pixels
  const x0 = 28 + 2 * Math.floor(noise(seed, 1) * 3) // her left dot column
  const hc = x0 >> 1
  const inZone = (col: number) => col >= hc - 2 && col <= hc + 4

  // The skyline: towers 4 columns wide, some gaps, roofs at world pixel 1 to 3;
  // her tower's roof is just under the frame (world pixel 4).
  const off = Math.floor(noise(seed, 2) * 4)
  const tower = (col: number) => {
    if (col >= hc - 1 && col <= hc + 3) return { roof: 4, id: -1 }
    const id = Math.floor((col + off) / 4)
    if ((col + off) % 4 === 3 && noise(seed, 3, id) < 0.6) return null
    return { roof: 1 + Math.floor(noise(seed, 4, id) * 3), id }
  }
  // A lit window at world pixel y of column col, or null.
  const windowAt = (col: number, y: number, roof: number): Ink | null => {
    const ph = Math.floor(noise(seed, 5, col) * 5)
    if (y <= roof || (y + ph) % 5 !== 0 || noise(seed, 6, col, y) < 0.3) return null
    if (dark) return null
    if (s === 0 && f < 1 + Math.floor(noise(seed, 7, col, y) * 10)) return null // the lights come on
    if (inZone(col)) return 'hot'
    const n = noise(seed, 8, col, y)
    return n < 0.3 ? 'spark' : n < 0.55 ? 'cool' : 'hot'
  }
  // A world pixel's ink: facade, roof rim (dim), window, or sky. While the
  // city streams past, the facades dim a step and the rims with them, so the
  // roofs scrolling through the cells never brighten many at once at 256 colors.
  const falling = s > 0 && !dark
  const world = (col: number, y: number): Ink | null => {
    const t = tower(col)
    if (!t || y < t.roof) return null
    if (dark) return dim('deep')
    if (y === t.roof) return falling ? c.mix('deep', 'base', 0.5) : dim('deep')
    return windowAt(col, y, t.roof) ?? (falling ? dim('deep') : 'deep')
  }

  for (let col = 0; col < 32; col++) {
    if (inZone(col) && s > 0) {
      // The drop: she falls down her tower's dark face, faded in over two frames
      // from an ember (a quarter of deep is near black at 256 colors, and the
      // second step would flash), while the lit facades stream past on both sides.
      for (let r = 0; r < 2; r++) c.bg(col, r, f === FALL ? c.mix('hot', 'base', 0.75) : c.mix('deep', 'base', 0.5))
    } else if (inZone(col)) {
      // Plates, so her dots can sit over the city: a cell takes its brighter pixel.
      for (let r = 0; r < 2; r++) {
        const top = world(col, s + 2 * r), bottom = world(col, s + 2 * r + 1)
        const ink = top === 'hot' || bottom === 'hot' ? 'hot' : bottom ?? top
        if (ink) c.bg(col, r, ink)
      }
    } else {
      for (let y = 0; y < 4; y++) {
        const ink = world(col, s + y)
        if (ink) c.pix(col, y, ink)
      }
    }
  }

  // The roof ledge she stands on, a hot rail at dot row 7, scrolling up with the city.
  const ledge = 7 - 2 * s
  if (ledge >= 0 && !dark) for (let x = (hc - 1) * 2; x < (hc + 4) * 2; x++) c.put(x, ledge, f < 2 ? dim('hot') : 'hot', 1)

  // The Major.
  const gone = f >= FADE[1] || dark
  if (!gone) {
    const pose = f < TIP ? STAND : SPREAD
    const tilt = f >= TIP && f < FALL ? 1 : 0
    const front = f - WIPE // the camo front's dot row; above it she is camo
    const fade = clamp((f - FADE[0]) / (FADE[1] - FADE[0]), 0, 1)
    const filled = (y: number, i: number) => pose[y]?.[i] === 'X'
    const edge = (y: number, i: number) => !(filled(y - 1, i) && filled(y + 1, i) && filled(y, i - 1) && filled(y, i + 1))
    pose.forEach((line, y) => {
      for (let i = 0; i < line.length; i++) {
        if (line[i] !== 'X') continue
        const x = x0 + i + (y < 4 ? tilt : 0)
        if (y < front) {
          // Camo: a hollow aqua outline that shimmers, each dot flipping within its cell.
          if (!edge(y, i) || noise(seed, 9, i, y) < fade) continue
          const flip = ((f >> 1) + y + i) % 3 === 0 ? 1 : 0
          c.put(x ^ flip, y, 'cool', 2)
        } else {
          c.put(x, y, f < 2 ? 'hot' : 'spark', 3)
        }
      }
    })
    // The scan line at the front, wider than she is.
    if (front >= 0 && front < 8) {
      for (let x = x0 - 3; x < x0 + 9; x++) c.put(x, front, 'spark', 4)
      for (let col = hc - 1; col <= hc + 3; col++) c.bg(col, front >> 2, c.mix('cool', 'base', 0.5))
    }
    // The coat falls away to the seed's side, frames 5 to 11.
    if (f >= 5 && f < 12) {
      const side = noise(seed, 10) < 0.5 ? -1 : 1
      const cx = x0 + 2 + side * (3 + ((f - 5) >> 1)), cy = 2 + (f - 5)
      for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1], [0, 2]] as const) if (cy + dy < 8) c.put(cx + dx, cy + dy, 'hot', 3)
    }
  }
}

function netDive(c: Canvas, f: number, seed: number) {
  const plate = c.mix('deep', 'base', 0.5)
  const center = 15 + Math.floor(noise(seed, 1) * 2)
  const sweepDir = noise(seed, 2) < 0.5 ? 1 : -1
  type Wave = { t0: number; origin: number; dir: 1 | -1; scheme: 0 | 1 | 2 }
  const waves: Wave[] = [
    { t0: SPLASH, origin: center + 0.5, dir: 1, scheme: 0 },
    { t0: SPLASH, origin: center - 0.5, dir: -1, scheme: 0 },
    { t0: ECHO, origin: -0.5, dir: 1, scheme: 1 },
    { t0: ECHO, origin: 31.5, dir: -1, scheme: 1 },
    { t0: SWEEP, origin: sweepDir === 1 ? -0.5 : 31.5, dir: sweepDir, scheme: 2 },
  ]
  // Echo fronts stop where they meet.
  const reach = (w: Wave) => (w.scheme === 1 ? 16 : 40)
  const SCHEMES: [Ink, Ink][][] = [
    [['spark', 'base'], ['hot', 'spark'], ['deep', 'cool']],
    [['cool', 'base'], [c.mix('cool', 'base', 0.25), 'base'], ['deep', 'cool']],
    [['hot', 'spark'], [c.mix('hot', 'deep', 0.5), 'hot'], [plate, 'hot']],
  ]
  for (let r = 0; r < 2; r++) {
    for (let col = 0; col < 32; col++) {
      let gen = 0
      let look: [Ink, Ink] = [plate, c.mix('cool', 'base', 0.5)]
      waves.forEach((w, k) => {
        if (f < w.t0) return
        const p = w.origin + w.dir * 2 * (f - w.t0 + 1) // the front, 2 columns a frame
        const behind = w.dir * (p - (col + w.dir * r * 0.5)) // the front slants a half column
        const travelled = w.dir * (col - w.origin)
        if (behind < 0 || travelled > reach(w) || travelled < 0) return
        gen = k + 1
        const stage = behind < 2 ? 0 : behind < 4 ? 1 : behind < 8 ? 2 : -1
        if (stage >= 0) look = SCHEMES[w.scheme]![stage]!
      })
      c.bg(col, r, look[0])
      // The diver drops into the center, frames 2 to 7; its cells hold dots, not digits.
      const diving = f >= 2 && f < SPLASH && (col === center || col === center + 1)
      const digit = gen === 0 || gen === waves.length ? noise(3, col, r) : noise(seed, 3, col, r, gen)
      if (!diving) c.glyph(col, r, HEX[Math.floor(digit * 16)]!, look[1])
    }
  }
  if (f >= 2 && f < SPLASH) {
    const y = (f - 2) * 1.5
    const x = center * 2 + 1
    // Head first: hands and head in yellow, a body and an aqua wake above.
    const diver = [[0, 0, 'spark'], [1, 0, 'spark'], [-1, -1, 'spark'], [2, -1, 'spark'], [0, -1, 'spark'], [1, -1, 'spark'], [0, -2, 'cool'], [1, -2, 'cool'], [0, -3, 'cool'], [1, -4, 'cool']] as const
    for (const [dx, dy, ink] of diver) if ((x + dx) >> 1 === center || (x + dx) >> 1 === center + 1) c.put(x + dx, y + dy, ink, 2)
  }
}

function lattice(c: Canvas, f: number, seed: number) {
  const tri = (u: number) => Math.min(7, Math.abs((((u % 16) + 16) % 16) - 8))
  const flow = Math.max(0, f - FLOW) // dots the lattice has flowed outward
  const reach = f < BLAZE ? 3 * f + 1 : 99
  const linkInk: Ink = f >= 44 || f === 0 ? c.mix('cool', 'base', 0.5) : f >= 40 ? c.mix('cool', 'base', 0.25) : 'cool'

  // Packets: the seed picks when each leaves the center, its side and its line.
  const packets = [0, 1, 2, 3, 4, 5].map(k => ({
    t0: 16 + k * 3 + Math.floor(noise(seed, 1, k) * 2),
    side: (k + Math.floor(noise(seed, 2) * 2)) % 2 ? -1 : 1, // alternate sides
    line: noise(seed, 3, k) < 0.5 ? 0 : 1,
  }))
  const packetAt = (k: number) => {
    const p = packets[k]!
    return f >= p.t0 && f < p.t0 + 12 ? 3 * (f - p.t0) : -1 // its u, 3 dots a frame
  }

  // The plates, a harlequin keyed to the lattice: the diamonds centered on the
  // top apexes dark red, the others darker, the crossings dim red. Every plate
  // is within 0.10 luminance of the others, so the flow costs no flashes.
  for (let col = 0; col < 32; col++) {
    const x = col * 2
    const u = x >= 32 ? x - 32 : 30 - x
    if (u >= reach) continue
    const k = (((u - flow) % 16) + 16) % 16
    const kind = (k >= 3 && k <= 5) || (k >= 11 && k <= 13) ? 2 : k >= 6 && k <= 10 ? 1 : 0
    let ink: Ink = kind === 2 ? c.mix('hot', 'base', 0.5) : kind === 1 ? 'deep' : c.mix('deep', 'base', 0.5)
    if (f < BLAZE) {
      const age = f - Math.floor(u / 3) // frames since the growth reached it
      if (kind === 2) ink = age <= 0 ? 'cool' : age === 1 ? c.mix('cool', 'base', 0.25) : age === 2 ? c.mix('cool', 'base', 0.5) : ink
    } else if (f < BLAZE + 2) ink = kind === 2 ? 'spark' : kind === 1 ? 'hot' : 'deep'
    else if (f < BLAZE + 5) ink = kind === 2 ? 'hot' : kind === 1 ? c.mix('hot', 'deep', 0.5) : ink
    if (f === 0) ink = c.mix('deep', 'base', 0.5)
    if (f >= 44 && kind === 1) ink = c.mix('deep', 'base', 0.25)
    // A packet lights the cell its head is in.
    for (let k2 = 0; k2 < packets.length; k2++) {
      const pu = packetAt(k2)
      if (pu >= 0 && (packets[k2]!.side === 1 ? 32 + pu : 31 - pu) >> 1 === col) ink = 'cool'
    }
    for (const r of [0, 1]) c.bg(col, r, ink)
  }

  // The two zigzags, mirrored about the center and flowing outward.
  for (let x = 0; x < 64; x++) {
    const u = x >= 32 ? x - 32 : 31 - x
    if (u >= reach) continue
    const y1 = tri(u - flow), y2 = 7 - y1
    const tip = f > 0 && f < BLAZE && u >= reach - 3
    const ink: Ink = tip ? 'spark' : f >= BLAZE && f < BLAZE + 2 ? 'spark' : linkInk
    c.put(x, y1, ink, 1)
    c.put(x, y2, ink, 1)
  }
  for (let k = 0; k < packets.length; k++) {
    const pu = packetAt(k)
    if (pu < 0) continue
    const p = packets[k]!
    for (let d = 0; d < 3; d++) {
      const u = pu - d
      if (u < 0) continue
      const x = p.side === 1 ? 32 + u : 31 - u
      const y = p.line === 0 ? tri(u - flow) : 7 - tri(u - flow)
      c.put(x, y, 'spark', 5 - d)
    }
  }
}

export default {
  name: 'ghost',
  title: 'Ghost line',
  source: 'Ghost in the Shell',
  contexts: ['edit', 'web:net-dive'],
  rare: false,
  variants: {
    camo: { loop: LOOP, beats: [{ at: WIPE, phrase: 'THERMOPTIC CAMO' }] },
    'net-dive': { loop: LOOP, beats: [{ at: SPLASH, phrase: 'DIVE // SECTION 9' }] },
    lattice: { loop: LOOP, beats: [{ at: BLAZE, phrase: 'THE NET IS VAST AND INFINITE' }] },
  },
  draw: (c, frame, seed, variant) => (variant === 'net-dive' ? netDive : variant === 'lattice' ? lattice : camo)(c, frame, seed),
} satisfies Reel

files.hooks/reels/kodama.ts:
import type { Canvas, Ink, Reel } from '../canvas'
import { noise } from '../canvas'

// Forest spirit (Princess Mononoke). One variant, walk, 108 frames, played on
// long waits. A night forest of dark red trunks over a mossy floor.
//
// Kodama rise out of the floor one by one, each 4 dots wide and 8 tall: a big
// round head with two eye holes on a thin body. KODAMA RATTLE: every head
// blazes yellow and they rattle in unison, tilting left, upright, right, then
// fall out of step. They sense something, all turn toward one side and sink
// back into the ground, nearest first.
//
// The curse demon charges in from that side: a dark boar shape covered in a
// writhing mass of short red worms, aqua tusks at its snout and one red eye.
// TATARIGAMI: it halts in the middle, the eye snaps open, worms lash out
// across the canvas and a red blight runs along the floor to both edges. Then
// it charges off the other side while the blight fades.
//
// Two kodama peek out of the floor, rattling, and duck as the Forest Spirit
// nears. The Forest Spirit, an aqua deer with a red face and a yellow crown of
// antlers, walks in. Where its hooves fall, flowers spring up, bloom, then wilt
// red and wither to nothing behind it. SHISHIGAMI WALKS: it halts mid-stride
// at the middle and a ring of flowers bursts open around its hooves, then it
// walks on and the ring withers.
//
// The seed picks how many kodama rise (4 to 6), where, when and how they fall
// out of step; the demon's side, where it halts, its worms and its lashes; and
// the flowers' heights and timing. The forest is seed-free, so the wrap from
// one loop to the next is seamless.

const LOOP = 108
const RATTLE = 12 // KODAMA RATTLE: the heads blaze and rattle in unison
const SENSE = 30 // the kodama turn toward the demon's side
const CHARGE = 38 // the demon enters
const CURSE = 48 // TATARIGAMI: it halts, the eye opens, the lashes fly
const LEAVE = 60 // it charges off
const PEEK = 67 // two kodama peek out
const WALK = 84 // SHISHIGAMI WALKS: the spirit halts at the middle
const HOLD = 8 // frames it stands there, mid-stride, while the ring blooms

const KODAMA = ['.XX.', 'XXXX', 'X..X', '.XX.', '.XX.', 'XXXX', '.XX.', 'X..X']
// The Forest Spirit facing right, 13 dots wide: antlers, head and snout, neck,
// body, legs; the last row strides.
const DEER = [
  '.......X.X.X.',
  '........XXX..',
  '.........XXXX',
  '........XX...',
  'X.XXXXXXXX...',
  '.XXXXXXXXX...',
  '.XX....XX....',
]
const STRIDE = ['X..X..X..X...', '.XX....XX....']

// Trunks, seed-free: the cells of these columns are dark red on both rows.
const TRUNKS = new Set([2, 6, 11, 17, 22, 27])

// A canvas where a cell belongs to whichever of pixels and dots reaches it
// first, so dots never erase pixels: the later layer skips a claimed cell.
function claiming(c: Canvas): Canvas {
  const owner = new Map<number, 'pix' | 'dot'>()
  const take = (col: number, row: number, kind: 'pix' | 'dot') => {
    if (col < 0 || col >= c.cols || row < 0 || row > 1) return false
    const k = row * 64 + col
    const o = owner.get(k)
    if (o && o !== kind) return false
    owner.set(k, kind)
    return true
  }
  return {
    cols: c.cols, rows: c.rows, mix: c.mix, bg: c.bg, glyph: c.glyph,
    pix: (x, y, ink) => {
      const [X, Y] = [Math.round(x), Math.round(y)]
      if (Y >= 0 && Y < 4 && take(X, Y >> 1, 'pix')) c.pix(X, Y, ink)
    },
    put: (x, y, ink, priority) => {
      const [X, Y] = [Math.round(x), Math.round(y)]
      if (Y >= 0 && Y < 8 && X >= 0 && X < 64 && take(X >> 1, Y >> 2, 'dot')) c.put(X, Y, ink, priority)
    },
  }
}

const sprite = (c: Canvas, rows: readonly string[], x: number, y: number, ink: (r: number) => Ink, prio: number, shift: (r: number) => number = () => 0) =>
  rows.forEach((line, r) => {
    for (let i = 0; i < line.length; i++) if (line[i] === 'X') c.put(x + i + shift(r), y + r, ink(r), prio)
  })

// The demon's side: -1 it enters from the left and runs right, 1 the reverse.
const sideOf = (seed: number) => (noise(seed, 5) < 0.5 ? -1 : 1)
const stopOf = (seed: number) => 15 + Math.floor(noise(seed, 6) * 2)

// The demon's center column at frame f, or null off stage.
function demonAt(seed: number, f: number): number | null {
  const side = sideOf(seed), stop = stopOf(seed)
  const start = side < 0 ? -7 : 38, end = side < 0 ? 38 : -7
  if (f < CHARGE || f > LEAVE + 11) return null
  if (f < CURSE) return start + ((stop - start) * (f - CHARGE)) / (CURSE - CHARGE)
  if (f < LEAVE) return stop + (f >= CURSE + 2 && f < CURSE + 8 ? ((f >> 1) % 2 ? 0.5 : -0.5) * side : 0)
  return stop + ((end - stop) * (f - LEAVE)) / 11
}

// The demon's body cells: the hump on row 0 sits back from the snout.
function inBody(cx: number, col: number, row: number, dir: number) {
  const d = (col - cx) * dir // positive toward the snout
  return row === 1 ? d >= -5 && d <= 5 : d >= -4 && d <= 2
}

function kodama(c: Canvas, f: number, seed: number) {
  const side = sideOf(seed)
  const n = 4 + Math.floor(noise(seed, 1) * 3)
  // Two of the four center slots, so the 16-column crop always holds two.
  const center = [2, 3, 4, 5].sort((a, b) => noise(seed, 2, a) - noise(seed, 2, b)).slice(0, 2)
  const rest = [0, 1, 2, 3, 4, 5, 6, 7].filter(s => !center.includes(s)).sort((a, b) => noise(seed, 3, a) - noise(seed, 3, b))
  const slots = [...center, ...rest.slice(0, n - 2)]
  const order = [...slots].sort((a, b) => noise(seed, 4, a) - noise(seed, 4, b))
  // The ones nearest the demon's side sink first.
  const byNear = [...slots].sort((a, b) => (side < 0 ? a - b : b - a))
  for (const slot of slots) {
    const i = order.indexOf(slot)
    const rise = 1 + Math.round((i * 8) / (n - 1)) // frame it starts to rise
    const sink = SENSE + 2 + byNear.indexOf(slot) // frame it starts to sink
    const depth = f < rise ? 8 : f < sink ? Math.max(0, 8 - 2 * (f - rise + 1)) : Math.min(8, 2 * (f - sink + 1))
    if (depth >= 8) continue
    let pose = 0
    if (f < RATTLE) {
      // A curious tilt, once, while it settles.
      const at = rise + 4 + Math.floor(noise(seed, 7, slot) * 3)
      if (f >= at && f < at + 2 && at <= RATTLE - 4) pose = noise(seed, 8, slot) < 0.5 ? -1 : 1
    } else if (f < RATTLE + 8) pose = [-1, 0, 1, 0][(f - RATTLE) % 4]!
    else if (f < RATTLE + 10) pose = 0
    else if (f < SENSE) pose = [-1, 0, 1, 0][((f + Math.floor(noise(seed, 9, slot) * 8)) >> 1) % 4]!
    else pose = side
    const blaze = f >= RATTLE && f < RATTLE + 8
    const x = 2 * (4 * slot + 1)
    sprite(c, KODAMA, x, depth, r => (r < 4 ? (blaze ? 'spark' : 'cool') : c.mix('cool', 'base', 0.25)), 4, r => (r < 2 ? pose : 0))
  }
}

// After the demon has gone, the two center kodama peek out, heads only, and
// rattle; each ducks back down just ahead of the Forest Spirit.
function peek(c: Canvas, f: number, seed: number) {
  const center = [2, 3, 4, 5].sort((a, b) => noise(seed, 2, a) - noise(seed, 2, b)).slice(0, 2)
  for (const slot of center) {
    const x = 2 * (4 * slot + 1)
    const rise = PEEK + Math.floor(noise(seed, 16, slot) * 3)
    const sink = Math.min(WALK - 3, WALK + Math.floor((x - 44) / 3))
    const depth = f < rise ? 8 : f < sink ? Math.max(4, 8 - 2 * (f - rise + 1)) : Math.min(8, 4 + 2 * (f - sink + 1))
    if (depth >= 8) continue
    const pose = [-1, 0, 1, 0][((f + slot) >> 1) % 4]!
    sprite(c, KODAMA.slice(0, 4), x, depth, () => 'cool', 4, r => (r < 2 ? pose : 0))
  }
}

function demon(c: Canvas, f: number, seed: number, cx: number) {
  const dir = -sideOf(seed) // the way it runs
  const front = 2 * cx + 1 + dir * 11 // the snout's dot column
  // The eye, drawn first so no worm covers it: shut to a slit until it halts.
  const eye = Math.round(cx + 2 * dir)
  c.pix(eye, 1, 'hot')
  if (f >= CURSE) c.pix(eye, 0, 'hot')
  // Tusks, curving up from the snout.
  for (const [dx, y] of [[0, 6], [1, 5], [1, 4]] as const) c.put(front + dir * dx, y, 'cool', 6)
  // The worms: short curling strands anchored on the body, writhing.
  for (let k = 0; k < 16; k++) {
    let x = 2 * cx + 1 + (noise(seed, 10, k) - 0.5) * 20
    let y = noise(seed, 11, k) * 8
    if (y < 4 && Math.abs(x - 2 * cx - 1 + dir * 2) > 7) y += 4
    const ph = noise(seed, 12, k) * 6.28
    let th = noise(seed, 13, k) * 6.28 + 1.4 * Math.sin(0.7 * f + ph)
    const bend = 0.8 * Math.sin(0.9 * f + ph * 1.7)
    const ink: Ink = k % 3 ? 'hot' : c.mix('hot', 'deep', 0.5)
    for (let i = 0; i < 4; i++) {
      c.put(x, Math.max(0, Math.min(7, y)), ink, 3)
      th += bend
      x += Math.cos(th)
      y += Math.sin(th)
    }
  }
  // TATARIGAMI: the lashes fly out to the edges, then draw back.
  if (f >= CURSE && f < LEAVE) {
    const s = f - CURSE
    for (let k = 0; k < 6; k++) {
      const way = k % 2 ? dir : -dir
      const max = 14 + Math.floor(noise(seed, 14, k) * 14)
      const len = Math.min(max, s < 8 ? 4 * (s + 1) : Math.max(0, max - 4 * (s - 7)))
      const y0 = 1 + ((k * 5 + Math.floor(noise(seed, 15, k) * 3)) % 6)
      const x0 = 2 * cx + 1 + way * 9
      for (let i = 0; i < len; i++) {
        const x = x0 + way * i
        c.put(x, Math.max(0, Math.min(7, y0 + 2.5 * Math.sin(x * 0.32 + f * 0.7 + k * 2.1))), 'hot', 2)
      }
    }
  }
}

// Where the Forest Spirit's left edge is, in dots: it halts at the middle
// for HOLD frames and otherwise walks 3 dots a frame.
const spiritX = (f: number) => 26 + 3 * (f < WALK ? f - WALK : Math.max(0, f - WALK - HOLD))

// The ring that bursts open around its hooves while it stands: columns either
// side of it, one more each way per frame.
const RING = [9, 10, 11, 12, 20, 21, 22, 23]
const ringAt = (col: number) => WALK + (col < 16 ? 12 - col : col - 20)

// The flower in a floor column: the frame it springs up and the frame it
// starts to wilt, or null if none grows there. A trail flower springs up as
// the hind hoof leaves the cell; a ring flower stays open until it walks on.
function bloomAt(seed: number, col: number): { at: number; wilt: number } | null {
  const jitter = Math.floor(noise(seed, 21, col) * 2)
  if (RING.includes(col)) return { at: ringAt(col), wilt: WALK + HOLD + jitter }
  if (noise(seed, 20, col) < 0.12) return null
  const trail = Math.ceil((2 * col - 25) / 3)
  const at = WALK + trail + (trail > 0 ? HOLD : 0) + jitter
  return { at, wilt: at + Math.floor(Math.min(12, LOOP - 1 - at) / 2) }
}

// Each flower is a dot stem on the floor row; a tall one opens its head in the
// cell above. It sprouts, blooms, wilts red, droops and withers, in 12 frames,
// or faster near the loop's end so every flower is gone by its last frame.
// Cells the Forest Spirit stands in hide their flower.
function blooms(c: Canvas, f: number, seed: number) {
  const sx = spiritX(f)
  for (let col = 0; col < 32; col++) {
    const b = bloomAt(seed, col)
    if (b === null || f < b.at) continue
    if (sx > -13 && sx < 64 && col >= sx >> 1 && col <= (sx + 12) >> 1) continue
    // Stages 0 to 5 grow and bloom, 6 to 11 wilt and wither.
    const wither = Math.max(1, Math.min(6, LOOP - 1 - b.wilt))
    const a = f < b.wilt ? Math.min(5, f - b.at) : 6 + Math.floor(((f - b.wilt) * 6) / wither)
    if (a >= 12) continue
    const x = 2 * col + (noise(seed, 22, col) < 0.5 ? 0 : 1)
    const tall = noise(seed, 23, col) < 0.6
    const n = noise(seed, 24, col)
    const flower: Ink = n < 0.65 ? 'spark' : n < 0.85 ? 'cool' : 'hot'
    const stem: Ink = a < 6 ? 'cool' : a < 8 ? c.mix('cool', 'base', 0.5) : 'deep'
    const head: Ink = a < 6 ? flower : a < 8 ? 'hot' : 'deep'
    const dots = (pts: readonly (readonly [number, number])[], ink: Ink) => pts.forEach(([dx, y]) => c.put(x + dx, y, ink, 2))
    if (a >= 10) { dots([[0, 7], [x % 2 ? -1 : 1, 7]], c.mix('deep', 'base', 0.25)); continue }
    if (tall) {
      // The stem grows a dot a frame to its full height, then slumps.
      const top = a >= 8 ? 6 : Math.max(4, 7 - a)
      for (let y = top; y < 8; y++) dots([[0, y]], stem)
      if (a >= 2 && a < 8) dots([[x % 2 ? -1 : 1, 6]], stem) // a leaf
      if (a >= 2 && a < 6) dots([[0, 3], [x % 2 ? -1 : 1, 3], [0, 2], [x % 2 ? -1 : 1, 2], [0, 1]], head)
      else if (a >= 6 && a < 8) dots([[0, 3], [x % 2 ? -1 : 1, 3], [x % 2 ? -1 : 1, 2]], head) // drooping
      else if (a >= 8) dots([[x % 2 ? -1 : 1, 5]], head) // fallen against the stem
    } else {
      // A short flower is one cell: a head on a stub, all in the flower's color.
      if (a < 2) dots([[0, 7], [0, 6 + (a ? -1 : 1)]], 'cool')
      else if (a < 8) dots(([[0, 7], [0, 6], [0, 5], [x % 2 ? -1 : 1, 5], [0, 4], [x % 2 ? -1 : 1, 4]] as const).slice(0, a < 6 ? 6 : 4), head)
      else dots([[0, 7], [x % 2 ? -1 : 1, 7]], head)
    }
  }
}

function spirit(c: Canvas, f: number) {
  const x0 = spiritX(f)
  if (x0 <= -13 || x0 >= 64) return
  // A faint aqua aura around it.
  for (let col = (x0 >> 1); col <= (x0 + 12) >> 1; col++) for (const row of [0, 1]) if (col >= 0 && col < 32) c.bg(col, row, c.mix('cool', 'base', 0.75))
  const face = (r: number): Ink => (r < 2 ? 'spark' : r === 2 ? 'hot' : 'cool')
  sprite(c, DEER, x0, 0, face, 5)
  sprite(c, [STRIDE[f >= WALK && f < WALK + HOLD ? 0 : (f >> 1) % 2]!], x0, 7, () => 'cool', 5)
}

function draw(canvas: Canvas, f: number, seed: number) {
  const c = claiming(canvas)
  const cx = demonAt(seed, f)
  const dir = -sideOf(seed)

  // The forest floor and trunks, then what the demon does to them. Moss grows
  // only on bare floor: on the blight a moss half-block in a cell that a worm
  // or lash dot crosses would swap with a braille cell a step brighter, so the
  // blight carries no moss and a dot crossing it never flashes, for any seed.
  const mossy: boolean[] = []
  for (let col = 0; col < 32; col++) {
    mossy[col] = !TRUNKS.has(col)
    for (const row of [0, 1]) {
      let ink: Ink | null = TRUNKS.has(col) ? c.mix('deep', 'base', 0.25) : row === 1 ? c.mix('deep', 'base', 0.5) : null
      // The blight: a red run along the floor from the halted demon to both edges.
      if (row === 1 && f >= CURSE) {
        const stop = stopOf(seed)
        const a = f - CURSE - Math.max(0, Math.abs(col - stop) - 5) / 2
        if (a >= 0 && a < 15) mossy[col] = false
        if (a >= 0) ink = a < 6 ? 'hot' : a < 9 ? c.mix('hot', 'deep', 0.5) : a < 12 ? 'deep' : a < 15 ? c.mix('deep', 'base', 0.25) : ink
      }
      if (cx !== null && inBody(cx, col, row, dir)) ink = row === 1 ? 'base' : c.mix('deep', 'base', 0.5)
      if (cx !== null && f >= CURSE && f < LEAVE && row === 0 && Math.abs(col - Math.round(cx + 2 * dir)) === 1) ink = c.mix('hot', 'base', 0.5)
      if (ink) c.bg(col, row, ink)
    }
  }

  // Pixels that must win their cells, then the figures in dots, then the rest.
  if (cx !== null) demon(c, f, seed, cx)
  else if (f < CHARGE) kodama(c, f, seed)
  if (f >= PEEK) peek(c, f, seed)
  blooms(c, f, seed)
  spirit(c, f)
  // Moss along the bare floor.
  for (let col = 0; col < 32; col++) if (mossy[col]) c.pix(col, 3, c.mix('cool', 'base', 0.75))
}

export default {
  name: 'kodama',
  title: 'Forest spirit',
  source: 'Princess Mononoke',
  contexts: ['long-wait'],
  rare: false,
  variants: {
    walk: {
      loop: LOOP,
      beats: [
        { at: RATTLE, phrase: 'KODAMA RATTLE' },
        { at: CURSE, phrase: 'TATARIGAMI' },
        { at: WALK, phrase: 'SHISHIGAMI WALKS' },
      ],
    },
  },
  draw: (c, frame, seed) => draw(c, frame, seed),
} satisfies Reel

